#82 - Activation Metrics

### Nome

Criar métricas de ativação

### Definição

Mensurar tempo até valor e ativação dos usuários.

---

### Código

```
// packages/modules/growth/activation/activation.service.ts
export class ActivationService {
  isActivated(events: string[], activationEvents: string[]) {
    return activationEvents.every(event => events.includes(event));
  }

  calculateActivationRate(totalUsers: number, activatedUsers: number) {
    if (totalUsers === 0) return 0;
    return (activatedUsers / totalUsers) * 100;
  }

  calculateTimeToValue(signupAt: Date, activatedAt: Date) {
    return activatedAt.getTime() - signupAt.getTime();
  }
}
```

